ervice/HierarchicalMod/siloFile/materialSave/materialSaveEdit?objEquId='' + selectRow.id;\n\t//窗口标题\n\tvar title = ReactAPI.international.getText(''HierarchicalMod.custom.random1618972964128'');\n\t//窗口名\n\tvar dialogName = ''batchingSequenceEdit'';\n\t//打开窗口\n\tReactAPI.createDialog(dialogName, {\n        title: title,\n        url: url,\n        width: ''800px'',\n        height: ''500px'',\n        isRef: false, // 是否开启参照\n        buttons: \n\t\t[\n\t\t\t{\n                text: ReactAPI.international.getText(''HierarchicalMod.custom.random1618817555709''),\n                type: \"primary\",\n                onClick: event => {\n                    // 提交当前iframe页面\n                    event.ReactAPI.submitFormData(\"save\", res => {\n                        if (res.success) {\n\t\t\t\t\t\t\t//保存成功时，关闭窗口\n                            ReactAPI.destroyDialog(dialogName);\n                        }\n                    });\n                }\n            }, \n\t\t\t{\n                text: ReactAPI.international.getText(''HierarchicalMod.custom.random1618817609741''),\n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\t\n}","funcname":"onclick=''modifyMaterialSave()''","buttonstyle":"edit","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1620450891602_1576","isHide":false,"showname":"物料存储设置","pc":"__pc__=SGllcmFyY2hpY2FsTW9kXzEuMC4wX2ZhY3RvcnlNb2RlbF9mYWN0b3J5RWRpdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"namekey":"HierarchicalMod.buttonPropertyshowName.randon1620450933141.flag","funcbody_es5":"function modifyMaterialSave() {\n    //获取料仓dataGrid对象\n    var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'');\n    //获取选中行对象\n    var selectRow = dataGrid.getSelecteds()[0];\n    //没有选中行\n    if (selectRow == undefined) {\n        ReactAPI.showMessage(''w'', ReactAPI.international.getText(\"HierarchicalMod.custom.random1618883059116\"));\n        return;\n    }\n    //选中行Id为undefined\n    if (selectRow.id == null || selectRow.id == undefined) {\n        ReactAPI.showMessage(''w'', ReactAPI.international.getText(\"HierarchicalMod.custom.random1621237858421\"));\n        return;\n    }\n    //窗口页面链接  参数为选中的关联设备id,根据关联设备id查询指定的物料管理信息以及物料分类管理信息\n    var url = ''/msService/HierarchicalMod/siloFile/materialSave/materialSaveEdit?objEquId='' + selectRow.id;\n    //窗口标题\n    var title = ReactAPI.international.getText(''HierarchicalMod.custom.random1618972964128'');\n    //窗口名\n    var dialogName = ''batchingSequenceEdit'';\n    //打开窗口\n    ReactAPI.createDialog(dialogName, {\n        title: title,\n        url: url,\n        width: ''800px'',\n        height: ''500px'',\n        isRef: false, // 是否开启参照\n        buttons: [{\n            text: ReactAPI.international.getText(''HierarchicalMod.custom.random1618817555709''),\n            type: \"primary\",\n            onClick: function onClick(event) {\n                // 提交当前iframe页面\n                event.ReactAPI.submitFormData(\"save\", function (res) {\n                    if (res.success) {\n                        //保存成功时，关闭窗口\n                        ReactAPI.destroyDialog(dialogName);\n                    }\n                });\n            }\n        }, {\n            text: ReactAPI.international.getText(''HierarchicalMod.custom.random1618817609741''),\n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(dialogName);\n            }\n        }]\n    });\n}","id":"modifyMaterialSave","operatetype":"CUSTOM","isconfirm":false}],"autoresize":false,"DataGridCode":"HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487","listPT":false,"renderOver_es5":"var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'');\ndataGrid.getDatagridData().forEach(function (item) {\n    console.log(item);\n    // 将没有勾选固定安装的设备位号设置不可编辑\n    if (!item.isFixed) {\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''equipmentNum'', { readonly: true });\n    }\n    // 将没有勾选是否容器的清空类型、储罐设置不可编辑\n    if (!item.isContainer) {\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''clearType.value'', { readonly: true });\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''objContainer.name'', { readonly: true });\n    } else {\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''selWareType.value'', { readonly: false });\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''objContainer.name'', { readonly: false });\n    }\n    // 将清空类型为空的清空位号设置不可编辑\n    if (!item.clearType) {\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''clearNum'', { readonly: true });\n    }\n    //补料模式为通知执行时,部门可编辑\n    if (item.runModel && item.runModel.id == ''HierarchicalMod_runModelCode1/noticeExecution'') {\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''objDepartment.name'', { readonly: false });\n    } else {\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''objDepartment.name'', { readonly: true });\n        dataGrid.setRowData(item.rowIndex, { objDepartment: null });\n    }\n    //补料模式为主动执行时，进料方式为空\n    // if(item.runModel && item.runModel.id == ''HierarchicalMod_runModelCode1/activeExecution'') {\n    //     dataGrid.setDatagridCellAttr(item.rowIndex, ''feedStockType.value'', {readonly: true});\n    //     dataGrid.setRowData(item.rowIndex, {feedStockType: null})\n    // }else {\n    //     dataGrid.setDatagridCellAttr(item.rowIndex, ''feedStockType.value'', {readonly: false});\n    // }\n    //物料编码不为null且物料维护选中批次时,批号可编辑\n    if (item.materialConfig && item.materialConfig.id == ''HierarchicalMod_materialConfigCode/batch'' && item.productId.code != null) {\n        dataGrid.setDatagridCellAttr(item.rowIndex, ''batchNum'', { readonly: false });\n    }\n\n    //当前数量转为超链接\n    var url = \"/msService/HierarchicalMod/factoryModel/ftyEquipment/batchDetailsView\";\n    url += \"?thisEquId=\" + item.id;\n    url += \"&customConditionKey=thisEquId\";\n    var defaultNum = dataGrid.getValueByKey(item.rowIndex, \"defaultNum\");\n    if (defaultNum != null) {\n        var htmlStr = ''<a style=\"padding: 0px 4px;text-Decoration:underline\" onclick=\"ReactAPI.createDialog(\\''attachPartRef\\'', {title:ReactAPI.international.getText(\\''HierarchicalMod.custom.random1619070584664\\''),url: \\'''' + url + ''\\'',size:5,buttons: []})\">'' + defaultNum + ''</a>'';\n    }\n    dataGrid.setFormatHtml(item.rowIndex, \"defaultNum\", htmlStr);\n});\n// 仓库确定方式为指定，仓库可编辑\nvar datagridData = dataGrid.getDatagridData();\nif (datagridData) {\n    for (var i = 0; i < datagridData.length; i++) {\n        if (datagridData[i].selWareType) {\n            if (datagridData[i].selWareType.value == \"指定\") {\n                dataGrid.setDatagridCellAttr(datagridData[i].rowIndex, ''wareId.code'', { readonly: false });\n                dataGrid.setDatagridCellAttr(datagridData[i].rowIndex, ''storeId.code'', { readonly: false });\n            }\n        }\n    }\n}\n// 货位状态设置不可编辑-融合环境界面设置只读不生效\ndataGrid.setDatagridCellAttr(rowIndex, ''wareId.storesetState'', { readonly: true });","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"datagrid","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak