isconfirm":false}],"autoresize":false,"DataGridCode":"HierarchicalMod_1.0.0_factoryModel_factoryEditdg1618565717483","listPT":false,"copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"datagrid","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-1","layoutmethod":"container","ptRealTimeLoad":0,"namekey":"HierarchicalMod.tabname.randon1618564137700.flag","name":"装卸点","isreadonly":0,"layno":2,"id":"tabs-24","tabCode":"tabs-25","layoutname":"tabs-25","islefttopfixed":false,"nums":1}],"isrightbottomfixed":false,"type":"layout","isreadonlyBak":0,"ptRealTimeLoad":1,"layoutmethod":"tab","namekey":"ec.view.commoninfo","name":"常规信息","isreadonly":0,"layno":1,"id":null,"tabCode":"tab_0","layoutname":"tabs-1","nums":7,"islefttopfixed":false}],"layoutmethod":"tab","type":"layout"}],"layoutmethod":"column","type":"layout"}],"enableSimpleDealInfo":false,"title":"HierarchicalMod.viewtitle.randon1573032446254","url":"/msService/HierarchicalMod/factoryModel/factoryModel/factoryEdit","dealInfoShow":false,"hasAttachment":false,"pageType":"EDIT","dealInfoGroup":"byTime","refCopy":{"isReference":false},"colNum":6,"layoutType":"classic","selfAdaption":false,"events":[{"function":"let nodeType = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue();\nif(nodeType.length) {\n    // 如果不从顶级节点创建，需要获取上一级节点\n    let parentId = ReactAPI.getParamsInRequestUrl().parentId ? ReactAPI.getParamsInRequestUrl().parentId : ReactAPI.getFormData().parentId;\n    if (parentId && parentId > 0) {\n        // 获取父节点\n        let parent = null;\n        ReactAPI.request(\n            {\n                type: \"get\",\n                url: \"/msService/HierarchicalMod/factoryModel/factoryModel/data/\" + parentId,\n                async: false\n            },\n            res => {\n                parent = res.data;\n            }\n        );\n        // 如果选择类型的id小于父节点类型的id\n        if (parent.nodeTypeId){\n            if (nodeType[0].id <= parent.nodeTypeId.id) {\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t  \n                ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1573436074669'', parent.nodeTypeId.name));\n                ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').setValidateStyle(''error'');\n                return false;\n            }\n        } \n    }\n    //检查当前节点是否是生产线、工作单元组、工作单元，如是，则判断上层节点否有工作区域\n    // let nodeTypeID = nodeType[0].id; \n    // if(nodeTypeID>=1003){\n    //     let IsWorkArea=false;\n    //     ReactAPI.request(\n    //         {\n    //             type: \"get\",\n    //             url: \"/msService/HierarchicalMod/factoryModel/factoryModel/getWorkShopIsEnable/\" + parentId,\n    //             async: false\n    //         },\n    //         res=>{\n    //             IsWorkArea = res.data.workArea;\n    //         });\n    //     if(!IsWorkArea){ \n    //         // 上级节点必须有生产区域类型的节点\n    //         ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1591840508749'', parent.nodeTypeId.name));\n    //         return false;\n    //     }\n    // }\n}\n\n// 设备页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'']) {\n\tlet equipDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'');\n    for (let item of equipDataGrid.getDatagridData()) {\n        // 设备位号和设备名称至少保证一个中有内容\n        if (item.isFixed) {\n            // 当固定位号勾选 时，设备位号和设备名称至少添加一项\n            if ((item.equipmentNum === null || !item.equipmentNum.trim()) && (item.objEqu === null || !item.objEqu.id)) {\n                let message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1585097165367'', ReactAPI.international.getText(''HierarchicalMod.tabnamenew2.randon1597233997319.flag''), item.rowIndex + 1);\n                ReactAPI.showMessage(\"f\", message);\n                return false;\n            }\n        } else {\n            // 当固定位号没有勾选时，设备名称需有内容 <b>页签【{0}】</b><br>“{1}” 第{2}行不允许为空！\n            if (item.name === null || !item.name) {\n                let message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1585105550077'', \n\t\t\t\t\tReactAPI.international.getText(''HierarchicalMod.tabnamenew2.randon1597233997319.flag''), ReactAPI.international.getText(''HierarchicalMod.equip.AccessoryDev.name''), item.rowIndex + 1);\n                ReactAPI.showMessage(\"f\", message);\n                return false;\n            }\n\t\t}\n\t\t\n\t\t// if (item.selWareType.value == \"指定\") {\n\t\t// \tif (!item.wareId.id) {\n\t\t// \t\t// <b>页签【{0}】</b><br> 第{1}行，仓库指定方式为【指定】，仓库不允许为空！\n\t\t// \t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1597389653474'', ''设备'', item.rowIndex + 1));\n\t\t// \t\treturn false;\n\t\t// \t}\n\t\t// }\n\n    }\n}\n// 仓库页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202120574'']) {\n    let wareDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202120574'');\n    for (let item of wareDataGrid.getDatagridData()) {\n        // 启用货位时，货位必填\n        if (item.objWareId && item.objWareId.warehouseState && item.objWareId.warehouseState.value && !item.objStoreId) {\n            let message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1573549406324'', ReactAPI.international.getText(''HierarchicalMod.factoryWareMaterial.FactoryMateria.wareId''), item.rowIndex + 1) + \"，\" + ReactAPI.international.getText(''HierarchicalMod.custom.randon1573549502918'');\n            ReactAPI.showMessage(\"f\", message);\n            return false;\n        }\n    }\n}\n\n//测点页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1597279515664'']) {\n    let tagDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1597279515664'');\n\t// 测点和测点标签不能重复\n    for (let item of tagDataGrid.getDatagridData()) {\n\t\tlet i = item.rowIndex;\n\t\tlet tagId = item.objTagId.id;\n\t\tlet paramLabel = item.paramLabel;\n\t\tfor (let item2 of tagDataGrid.getDatagridData()) {\n\t\t\tif(i != item2.rowIndex){\n\t\t\t\tif (item2.objTagId.id == tagId) {\n\t\t\t\t\tlet message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1599793866407'', i+1, item2.rowIndex+1,\n\t\t\t\t\t\tReactAPI.international.getText(''HierarchicalMod.technologyCard.TechCard.tagNameStr''));\n\t\t\t\t\tReactAPI.showMessage(\"f\", message);\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\t\t\t\tif(item2.paramLabel == paramLabel){\n\t\t\t\t\tlet message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1599793866407'', i+1 , item2.rowIndex+1,\n\t\t\t\t\t\tReactAPI.international.getText(''HierarchicalMod.factoryModel.TagInfos.paramLabel''));\n\t\t\t\t\tReactAPI.showMessage(\"f\", message);\n\t\t\t\t\treturn false;\n\t\t\t\t}\t\n\t\t\t}\n\t\t}\n    }\n}","name":"onsave"},{"function":"//隐藏装置tab\n//ReactAPI.Layout.hideTab(\"tabs-29\");\n$(\"#factoryModel_endItemId_name\").attr(\"style\", \"display:none;\");\n$(\"#label_factoryModel_endItemId_name\").attr(\"style\", \"display:none;\");\n$(\"#factoryModel_assignBatchNoId_name\").attr(\"style\", \"display:none;\");\n$(\"#label_factoryModel_assignBatchNoId_name\").attr(\"style\", \"display:none;\");\n\n//生产区域id\n$(\"#label_factoryModel_workshopId\").attr(\"style\", \"display:none;\");\n$(\"#factoryModel_workshopId\").attr(\"style\", \"display:none;\");\n\n//生产区域id\n$(\"#label_factoryModel_lineId\").attr(\"style\", \"display:none;\");\n$(\"#factoryModel_lineId\").attr(\"style\", \"display:none;\");\n\nvar nodeTypes = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue();\nif (nodeTypes.length) {\n    var code = nodeTypes[0].code;\n    if (code == ''006'' || code == ''005'') {\n        ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'').setReadonly(false);\n        //配料系统值可编辑\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setReadonly(false);\n    }\n    //获取节点类型,如果为节点类型为生产线/过程组元/生产单元时，“是否包装线”可以编辑，装置可编辑\n    if (code == \"004\") {\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setReadonly(false);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').setReadonly(false);\n    }\n}\nvar selWareTypeSystemCode = ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'');\nvar selWareType = selWareTypeSystemCode.getValue();\nif (selWareType.value) {\n    // 指定\n    if (selWareType.value == ''HierarchicalMod_selWareType/allocate'') {\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setRequired(true);\n        ReactAPI.getComponentAPI().Label.APIs(''factoryModel.wareId.code'').setNullableStyle(true);\n\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(false);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(false);\n        var storesetState = ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.wareId.storesetState'').getValue();\n        if (storesetState.value) {\n            ReactAPI.getComponentAPI().Label.APIs(''factoryModel.storeId.code'').setNullableStyle(true);\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setRequired(true);\n        }\n    }\n    // 映射\n    if (selWareType.value == ''HierarchicalMod_selWareType/mapping'') {\n        // 是否只读\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(true);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(true);\n    }\n}\n\n// 隐藏仓库与计量点\n//$(''.ant-tabs-nav-wrap .ant-tabs-tab:gt(5)'').hide();\nif (ReactAPI.getParamsInRequestUrl().id) {\n    // 节点编码字段不能修改\n    ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.code'').setReadonly(true);\n    // 如果已选外部系统，则外部系统也不能修改\n    if (ReactAPI.getFormData().isOtherSystem) {\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.objFactoryIdSystemObjId'').setReadonly(true);\n    }\n    // 节点类型\n    var _nodeTypes = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue();\n    if (_nodeTypes.length && _nodeTypes[0].id <= 1002) {\n        // 如果选择的节点为“企业”、“工厂”、“生产区域”时，部门必填\n        ReactAPI.getComponentAPI(''Reference'').APIs(\"factoryModel.departmentId.name\").setRequired(true);\n        ReactAPI.getComponentAPI(''Label'').APIs(\"factoryModel.departmentId.name\").setNullableStyle(true);\n    }\n}\n// 新增时\nelse {\n        // 有父节点\n        if (ReactAPI.getParamsInRequestUrl().parentId && ReactAPI.getParamsInRequestUrl().parentId > 0) {\n            // 获取父节点\n            ReactAPI.request({\n                type: \"get\",\n                data: {},\n                url: \"/msService/HierarchicalMod/factoryModel/factoryModel/data/\" + ReactAPI.getParamsInRequestUrl().parentId\n            }, function (res) {\n                console.log(res);\n                if (res.code == 200) {\n                    var 